files.check.bx:
// Judges a star document, all three layers, through star's PUBLIC surface.
//
// **Not star's own `examples/check.bx`, and the reason is a real constraint worth knowing.** Building a
// dependency's tool from inside its checkout fails: the compiler walks up from that file, finds STAR's
// `burxt.package`, and looks for star's own `.burxt/` — which does not exist in a consumer's tree.
// `use "bmx/burxt/bmx.bx" needs the dependency bmx, and it has not been fetched` is what that looks
// like, and no amount of fetching in /work fixes it. **A package's tools are not buildable from a
// consumer's checkout.**
//
// So this uses the six names star publishes, which is what they are published for. Three layers:
//
//   1. star's own rules      star_generate refuses with a STAR-Ennn or a BMX-Ennn
//   2. the component         star_source_of gives the Burxt the document became
//   3. the compiler          which is the layer that makes star worth using at all
use "star/star.bx";
use "std/files.bx";
use "std/os.bx";

if os_arg_count() < 2 {
    print_error("usage: star-check <document.sbmx>");
    exit(2);
}
let path: String = os_arg(1);
match star_generate(file_read(path), "showcase", []) {
    Error(why) => {
        print_error(why);
        exit(1);
    }
    Ok(built) => {
        let component: String = star_source_of(built, "showcase");
        let wrote: Int = file_write("/work/showcase.bx", component);
        if wrote < 0 {
            print_error("the document generated, but the component could not be written");
            exit(2);
        }
        // **The third layer, and the one a reader is really asking about.** A document can satisfy
        // star's rules and still produce a component the compiler refuses — a handler whose types do
        // not line up, a slot naming a field that is not there. That refusal is the answer.
        let judged: Capture = os_capture_status("burxt check /work/showcase.bx 2>&1");
        if judged.code != 0 {
            print_error(judged.output + judged.errors);
            exit(1);
        }
        print("this document generates a component the compiler accepts.");
        print("");
        print(component);
    }
}
